const TAG = '[PageContext]';

class PageContext {
  pathStack;

  constructor() {
    this.pathStack = new NavPathStack();
  }

  get navPathStack() {
    return this.pathStack;
  }

  replacePage(data, animated = true) {
    try {
      this.pathStack.pushPath({
        name: data.routerName,
        param: data.param,
      }, animated);
      return true;
    } catch (err) {
      Logger.error(TAG, `Open Page ${data.routerName} failed. ${err.code} ${err.message}.`);
      return false;
    }
  }

  openPage(data, animated = true) {
    try {
      this.pathStack.pushPath({
        name: data.routerName,
        param: data.param,
      }, animated);
      return true;
    } catch (err) {
      Logger.error(TAG, `Open Page ${data.routerName} failed. ${err.code} ${err.message}.`);
      return false;
    }
  }

  popPage(animated = true) {
    try {
      this.pathStack.pop(animated);
      return true;
    } catch (err) {
      Logger.error(TAG, `Pop Page failed. ${err.code} ${err.message}.`);
      return false;
    }
  }

  popPageByIndex(index, animated = true) {
    try {
      this.pathStack.popToIndex(index, animated);
      return true;
    } catch (err) {
      Logger.error(TAG, `PopToIndex failed. ${err.code} ${err.message}.`);
      return false;
    }
  }

  clear(animated = true) {
    try {
      this.pathStack.clear(animated);
      return true;
    } catch (err) {
      Logger.error(TAG, `Clear Page failed. ${err.code} ${err.message}.`);
      return false;
    }
  }
}

